    $j${"allowed_activities": "see definition_verbatim", "code": "C10", "definition_verbatim": "melakukan kegiatan pertemuan, insentif, konvensi, dan pameran, atau kegiatan sejenis lain sebagai narasumber, penceramah, atau penyaji maupun orang yang berpengaruh. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "single", "extendable": ["Anda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari.", "Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas dengan penjamin yang sama."], "jenis_visa_verbatim": "Visa C10 merupakan Visa Kunjungan untuk satu kali masuk ke Indonesia dengan izin tinggal pertama kali maksimal 60 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas dengan penjamin yang sama.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Kunjungan diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Orang Asing dengan izin tinggal dari Visa C10 diperkenankan menerima imbalan, upah, atau sejenisnya dari perorangan atau korporasi di Indonesia. Namun tidak diperbolehkan bekerja dalam hubungan kerja dengan perorangan atau korporasi di Indonesia."], "notes": ["Page shows no explicit offshore/onshore statement; where_to_apply is null. Application is via evisa.imigrasi.go.id per page text. Requirements numbered by order of appearance (page uses bullets, not numbers)."], "official_name_id": "C10 Visa Kunjungan Narasumber Kegiatan Bisnis", "page_sha256": "6a84344a6f39da65bc93b48625a314e95d979f610e3c51bb9d5006769bd09f78", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori. Setelah memiliki akun, penjamin dapat mengajukan visa C10 bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "pnbp_verbatim_for_reference_only": ["Masa tinggal 60 hari (bisa diperpanjang): Rp. 2.000.000", "Komponen biaya:", "- Biaya visa Rp 1.000.000", "- Biaya Verifikasi I Rp 1.000.000", "- Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing dengan izin tinggal dari Visa C10 diperkenankan menerima imbalan, upah, atau sejenisnya dari perorangan atau korporasi di Indonesia. Namun tidak diperbolehkan bekerja dalam hubungan kerja dengan perorangan atau korporasi di Indonesia."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "surat permohonan dan surat pernyataan penjamin,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan);"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin sebesar minimal USD2000 atau dalam mata uang lain yang setara jumlahnya,"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Persyaratan Khusus", "text": "surat undangan dari penyelenggara kegiatan yang menjelaskan rincian agenda dan materi ceramah/seminar yang akan disampaikan."}], "retrieved_at": "2026-10-17T10:08:17Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C10", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 60 hari, dihitung sejak tanggal kedatangan."], "where_to_apply": null}$j$::jsonb,
