bers)."], "official_name_id": "C12 Visa Kunjungan Pra-Investasi", "page_sha256": "86964d7df56173972616ac5d408b3d2311463185f6dd88013a753a68733d3914", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori. Setelah memiliki akun, penjamin dapat mengajukan visa C12 bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "pnbp_verbatim_for_reference_only": ["Masa tinggal 60 Hari : Rp. 3.000.000,-", "Komponen biaya:", "- Biaya visa Rp1.000.000", "- Biaya Verifikasi II Rp 2,000,000", "Masa tinggal 180 Hari : Rp. 4.000.000,-", "Komponen biaya:", "- Biaya visa C12 Rp 2.000.000", "- Biaya Verifikasi II Rp 2,000,000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing dengan izin tinggal dari Visa C12 dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "surat permohonan dan surat pernyataan penjamin,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis, (untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan);"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia sebesar minimal USD2000 atau dalam mata uang lain yang setara jumlahnya, seperti: rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin; atau slip gaji terbaru; atau deposito berjangka;"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "Tiket kembali"}, {"n": 6, "section": "Persyaratan Khusus", "text": "surat keterangan, undangan, atau korespondensi dari instansi pemerintah atau lembaga swasta yang menjelaskan hubungan dengan Orang Asing bersangkutan."}], "retrieved_at": "2026-10-17T10:08:17Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C12", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 180 hari, dihitung sejak tanggal kedatangan."], "where_to_apply": null}$j$::jsonb,
