    NULL,
    60,
    TRUE,
    180,
    NULL,
    NULL,
    $j${"allowed_activities": "see definition_verbatim", "code": "C2", "definition_verbatim": "berbisnis, mengikuti rapat, serta melakukan pembelian barang. Anda juga dapat melakukan pembicaraan, pembahasan, negosiasi, dan/atau menandatangani perjanjian bisnis. Visa ini memungkinkan anda melakukan pengecekan barang di kantor, pabrik, atau tempat produksi barang. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "single", "extendable": ["Anda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari.", "Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas."], "jenis_visa_verbatim": "Visa C2 merupakan Visa Kunjungan untuk satu kali masuk ke Indonesia dengan izin tinggal pertama kali maksimal 60 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Kunjungan diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Orang Asing dengan izin tinggal dari visa ini dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."], "notes": ["Persyaratan Khusus is a single un-bulleted line on page. Sponsor exception list as C1 (country list is a link).", "Page shows no explicit offshore/onshore statement; where_to_apply is null. Application is via evisa.imigrasi.go.id per page text. Requirements numbered by order of appearance (page uses bullets, not numbers)."], "official_name_id": "C2 Visa Kunjungan Bisnis", "page_sha256": "ca5ddd6fa7e69cc3c8e74b8f6dba15025c31ead9df70126f58791f67a0433dbe", "pengajuan_intro_verbatim": "Orang asing harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa. Setelah memiliki akun, orang asing dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "pnbp_verbatim_for_reference_only": ["Masa tinggal 60 hari (dapat diperpanjang) : Rp. 2.000.000", "Komponen biaya:", "- Biaya visa C2 Rp 1.000.000", "- Biaya Verifikasi I Rp 1.000.000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing dengan izin tinggal dari visa ini dilarang menjual barang atau jasa atau menerima imbalan, upah, atau sejenisnya atas kerja/usahanya dari perorangan atau korporasi di Indonesia."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\n(untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 4, "section": "Persyaratan Khusus", "text": "Surat keterangan/undangan/korespondensi dari instansi pemerintah atau lembaga swasta yang menjelaskan hubungan dengan Orang Asing bersangkutan."}], "retrieved_at": "2026-10-17T10:08:17Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C2", "sponsor_required": {"as_stated_boolean": false, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini.", "Kecuali anda:", "- Berstatus tanpa kewarganegaraan (stateless); atau", "- Pemegang dokumen perjalanan bukan paspor kebangsaan; atau", "- Warga negara dari negara tertentu yang ada di dalam daftar ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 60 hari, dihitung sejak tanggal kedatangan."], "where_to_apply": null}$j$::jsonb,
    'https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C2',
