    'C7A Visa Kunjungan Penampilan Musik',
    'Visit Visa',
    'C',
    'C7A Visa Kunjungan Penampilan Musik',
    'VISIT_SINGLE',
    TRUE,
    $j$[{"category": "single_entry_visas", "item_key": "C7A,B,C Music/Art"}]$j$::jsonb,
    'SINGLE',
    'REQUIRED',
    NULL,
    30,
    FALSE,
    30,
    NULL,
    NULL,
    $j${"allowed_activities": "see definition_verbatim", "code": "C7A", "definition_verbatim": "melakukan kegiatan seni dan budaya di Indonesia seperti memperlihatkan, menampilkan atau mempertunjukkan (perform) suatu karya yang berhubungan dengan musik. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "single", "extendable": ["Anda tidak dapat memperpanjang izin tinggal ini."], "jenis_visa_verbatim": "Visa C7A merupakan Visa Kunjungan untuk satu kali masuk ke Indonesia dengan izin tinggal maksimal 30 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini tidak dapat diperpanjang ataupun dialihkan menjadi Izin Tinggal lainnya.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Kunjungan diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Orang Asing dengan izin tinggal dari visa ini diperkenankan menerima imbalan atau fasilitas atas atas aktivitasnya. Namun dilarang bekerja dalam hubungan kerja dengan perorangan atau korporasi di Indonesia", "Orang Asing dengan izin tinggal dari visa ini dilarang menampilkan seni, budaya, atau perilaku yang tidak sesuai dengan peraturan atau norma yang berlaku."], "notes": ["Jenis visa says izin tinggal maksimal 30 hari, tidak dapat diperpanjang ataupun dialihkan.", "Bracketed qualifiers in Persyaratan Khusus distinguish general arts/culture participants from music performers/supporters.", "Page shows no explicit offshore/onshore statement; where_to_apply is null. Application is via evisa.imigrasi.go.id per page text. Requirements numbered by order of appearance (page uses bullets, not numbers)."], "official_name_id": "C7A Visa Kunjungan Penampilan Musik", "page_sha256": "6b290e978f8e8f292d3a78dca563ac66873eb87962538196a8958ec9088bad81", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori. Setelah memiliki akun, penjamin dapat mengajukan visa ini bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "pnbp_verbatim_for_reference_only": ["Masa tinggal 30hari : Rp. 1.500.000", "- Biaya visa C7A Rp 500.000", "- Biaya Verifikasi I Rp 1.000.000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing dengan izin tinggal dari visa ini diperkenankan menerima imbalan atau fasilitas atas atas aktivitasnya. Namun dilarang bekerja dalam hubungan kerja dengan perorangan atau korporasi di Indonesia", "Orang Asing dengan izin tinggal dari visa ini dilarang menampilkan seni, budaya, atau perilaku yang tidak sesuai dengan peraturan atau norma yang berlaku."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "surat pernyataan penjamin dari penyelenggara kegiatan,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\n(untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan)"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Persyaratan Khusus", "text": "surat undangan dari penyelenggara kegiatan (bagi pelaku kegiatan seni dan budaya yang bersifat umum); atau"}, {"n": 6, "section": "Persyaratan Khusus", "text": "surat penjaminan dan surat permohonan visa dari impresariat dan kontrak kerja sama penampil dengan penyelenggara kegiatan (bagi penampil musik atau pendukung)."}], "retrieved_at": "2026-10-17T10:08:17Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C7A", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 30 hari, dihitung sejak tanggal kedatangan."], "where_to_apply": null}$j$::jsonb,
