    NULL,
    60,
    TRUE,
    180,
    NULL,
    NULL,
    $j${"allowed_activities": "see definition_verbatim", "code": "C8A", "definition_verbatim": "melakukan kegiatan olahraga yang tidak bersifat komersial seperti mengikuti kegiatan olahraga atas undangan pemerintah Indonesia, kejuaraan olahraga tingkat internasional, atau kegiatan olahraga yang diselenggarakan oleh organisasi keolahragaan internasional sebagai atlet. Termasuk dengan visa ini anda dapat berwisata serta mengunjungi teman dan keluarga.", "entry": "single", "extendable": ["Anda dapat memperpanjang izin tinggal ini beberapa kali hingga maksimal 180 hari.", "Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas dengan penjamin yang sama."], "jenis_visa_verbatim": "Visa C8A merupakan Visa Kunjungan untuk satu kali masuk ke Indonesia dengan izin tinggal pertama kali maksimal 60 hari, dihitung sejak tanggal kedatangan. Izin Tinggal ini dapat diperpanjang dan dapat dikonversikan menjadi Izin Tinggal Terbatas dengan penjamin yang sama.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Kunjungan diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Orang Asing dengan izin tinggal dari visa ini diperkenankan menerima imbalan atau fasilitas atas atas aktivitasnya dari perorangan atau korporasi di Indonesia."], "notes": ["A vs B distinction (atlet vs ofisial) appears only in the Dengan visa definition; Persyaratan Khusus text is identical.", "Page shows no explicit offshore/onshore statement; where_to_apply is null. Application is via evisa.imigrasi.go.id per page text. Requirements numbered by order of appearance (page uses bullets, not numbers)."], "official_name_id": "C8A Visa Kunjungan Atlet Olahraga", "page_sha256": "1a9008ae555a3e3eff9f7c2449672b46df2764f20f743f365dbd85cb1efcdee3", "pengajuan_intro_verbatim": "Penjamin (sponsor) harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa bagi Orang Asing yang dia sponsori. Setelah memiliki akun, penjamin dapat mengajukan visa C8A bagi Orang Asing setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "pnbp_verbatim_for_reference_only": ["Masa tinggal 60 hari (bisa diperpanjang): Rp. 2.000.000", "Komponen biaya:", "- Biaya visa C8A Rp 1.000.000", "- Biaya Verifikasi II Rp 1.000.000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Orang Asing dengan izin tinggal dari visa ini diperkenankan menerima imbalan atau fasilitas atas atas aktivitasnya dari perorangan atau korporasi di Indonesia."], "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "surat permohonan dan surat pernyataan penjamin,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "dokumen perjalanan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,\n(untuk pemegang dokumen perjalanan selain paspor kebangsaan seperti paspor darurat, dokumen identitas, dll harus berlaku selama 12 bulan);"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Persyaratan Khusus", "text": "surat undangan dan surat sponsor dari penyelenggara kegiatan"}], "retrieved_at": "2026-10-17T10:08:17Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/C8A", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat tinggal di Indonesia maksimal 60 hari, dihitung sejak tanggal kedatangan."], "where_to_apply": null}$j$::jsonb,
